; ---------------------------------------------------------------
; RAYBENCH - textured raycaster benchmark for the VZ300
; mode 1 (128x64, 4 colours), no interrupts, field sync polled
; VIBED BY BPM 2026
; Tables (DXLO, LOGD, SCALE, records ...) are generated by build.py
; ---------------------------------------------------------------
        org $8000
start:  di
        ld sp,stacktop
        xor a
        ld (curtest),a
testloop:
        ld a,(curtest)
        call setmode
        ld a,$08
        ld ($6800),a            ; mode 1, colour set 0
        ld hl,$7000
        ld de,$7001
        ld bc,$07FF
        ld (hl),0
        ldir
w1:     ld a,($6800)            ; wait for field sync to start
        rlca
        jr nc,w1
w2:     ld a,($6800)
        rlca
        jr c,w2
        xor a
        ld (lastfs),a
        ld hl,0
        ld (fields),hl
        ld hl,PATH
        ld (pathptr),hl
        ld a,32
        ld (frcnt),a
fl:     ld hl,(pathptr)
        ld de,px
        ld bc,6
        ldir
        ld (pathptr),hl
        call render
frame_done:
        ld hl,frcnt
        dec (hl)
        jr nz,fl
        call poll
test_done:
        ld a,(curtest)
        add a,a
        ld e,a
        ld d,0
        ld hl,results
        add hl,de
        ld de,(fields)
        ld (hl),e
        inc hl
        ld (hl),d
        ld a,(curtest)
        inc a
        ld (curtest),a
        cp 4
        jp nz,testloop

; ---------------- results screen (text mode) -------------------
showres:
        xor a
        ld ($6800),a
        ld hl,$7000
        ld de,$7001
        ld bc,$01FF
        ld (hl),$20
        ldir
        ld hl,TXT
tl:     ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,d
        or e
        jr z,tdone
tc:     ld a,(hl)
        inc hl
        cp $FF
        jr z,tl
        ld (de),a
        inc de
        jr tc
tdone:  xor a
        ld (curtest),a
nl:     ld a,(curtest)
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,$70AF             ; row 5, column 15
        add hl,de
        ld (scrpos),hl
        ld a,(curtest)
        add a,a
        ld e,a
        ld d,0
        ld hl,results
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        ld (val),hl
        ld de,(scrpos)
        call print5s
        inc de
        push de
        ld a,(curtest)
        add a,a
        ld e,a
        ld d,0
        ld hl,EXPECT
        add hl,de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        pop de
        call print5s
        inc de
        push de
        ld de,(val)             ; fps x 10 = 16000 / fields
        ld a,d
        or e
        jr nz,nz1
        inc de
nz1:    ld hl,16000
        ld bc,0
dv:     or a
        sbc hl,de
        jr c,dvd
        inc bc
        jr dv
dvd:    ld h,b
        ld l,c
        ld de,numbuf
        call print5
        ld hl,numbuf+1
        ld b,2
        call supp
        pop de
        ld hl,numbuf+1
        ld a,(hl)
        ld (de),a
        inc de
        inc hl
        ld a,(hl)
        ld (de),a
        inc de
        inc hl
        ld a,(hl)
        ld (de),a
        inc de
        inc hl
        ld a,$2E
        ld (de),a
        inc de
        ld a,(hl)
        ld (de),a
        ld a,(curtest)
        inc a
        ld (curtest),a
        cp 4
        jp nz,nl
keywait:
        ld a,($68F7)            ; row: 4 1 3 - 2 5  (bits 5..0)
        ld c,0
        bit 4,a
        jr z,walkstart
        inc c
        bit 1,a
        jr z,walkstart
        inc c
        bit 3,a
        jr z,walkstart
        inc c
        bit 5,a
        jr z,walkstart
        jr keywait

; ---------------- walk-about mode -------------------------------
walkstart:
        ld a,c
        call setmode
        ld a,$08
        ld ($6800),a
        ld hl,$0280
        ld (px),hl
        ld hl,$0580
        ld (py),hl
        ld hl,0
        ld (pang),hl
wl:     ld hl,0
        ld (fields),hl
        call render
        call poll
        ld a,(fields)           ; fields this frame -> movement steps, so
        inc a                   ; walking speed is the same in every mode
        srl a
        jr nz,ws1
        inc a
ws1:    cp 7
        jr c,ws2
        ld a,6
ws2:    ld (steps),a
        ld a,($68FE)            ; row: R Q E - W T
        bit 4,a
        jp z,showres            ; Q = back to results
        ld a,($68F7)
        ld c,0
        bit 4,a
        jr z,wmode
        inc c
        bit 1,a
        jr z,wmode
        inc c
        bit 3,a
        jr z,wmode
        inc c
        bit 5,a
        jr nz,wturn
wmode:  ld a,c
        call setmode
wturn:  ld a,($68FD)            ; row: F A D CTRL S G
        bit 4,a
        jr nz,wt2
        ld de,$FFF8             ; A = turn left
        call turn
wt2:    ld a,($68FD)
        bit 3,a
        jr nz,wt3
        ld de,8                 ; D = turn right
        call turn
wt3:    ld a,($68FE)
        bit 1,a
        jr nz,wt4
        call getvec             ; W = forward
        call move
wt4:    ld a,($68FD)
        bit 1,a
        jr nz,wt5
        call getvec             ; S = back
        ld de,(vx)
        call negde
        ld (vx),de
        ld de,(vy)
        call negde
        ld (vy),de
        call move
wt5:    ld hl,steps
        dec (hl)
        jr nz,wturn
        jp wl

turn:   ld hl,(pang)
        add hl,de
        ld a,h
        and 3
        ld h,a
        ld (pang),hl
        ret

getvec: ld hl,(pang)            ; vx,vy = facing direction / 8
        ld a,h
        add a,ACOS_HI
        ld h,a
        ld a,(hl)
        rrca
        rrca
        rrca
        and $1F
        ld e,a
        ld d,0
        ld a,(pang+1)
        inc a
        and 2
        call nz,negde
        ld (vx),de
        ld hl,(pang)
        ld a,h
        add a,ASIN_HI
        ld h,a
        ld a,(hl)
        rrca
        rrca
        rrca
        and $1F
        ld e,a
        ld d,0
        ld a,(pang+1)
        and 2
        call nz,negde
        ld (vy),de
        ret
negde:  xor a
        sub e
        ld e,a
        sbc a,a
        sub d
        ld d,a
        ret

move:   ld hl,(vx)              ; try x, probing two steps ahead
        add hl,hl
        ex de,hl
        ld hl,(px)
        add hl,de
        ld a,(py+1)
        add a,a
        add a,a
        add a,a
        add a,a
        or h
        ld l,a
        ld h,MAP_HI
        ld a,(hl)
        or a
        jr nz,mv2
        ld hl,(px)
        ld de,(vx)
        add hl,de
        ld (px),hl
mv2:    ld hl,(vy)
        add hl,hl
        ex de,hl
        ld hl,(py)
        add hl,de
        ld a,h
        add a,a
        add a,a
        add a,a
        add a,a
        ld hl,px+1
        or (hl)
        ld l,a
        ld h,MAP_HI
        ld a,(hl)
        or a
        ret nz
        ld hl,(py)
        ld de,(vy)
        add hl,de
        ld (py),hl
        ret

; ---------------- helpers ---------------------------------------
setmode:
        ld e,a
        add a,a
        add a,a
        add a,e
        ld e,a
        ld d,0
        ld hl,MODES
        add hl,de
        ld de,m_ncols
        ld bc,5
        ldir
        ret

poll:   ld a,($6800)            ; count field sync falling edges
        and $80
        ld hl,lastfs
        cp (hl)
        ret z
        ld (hl),a
        or a
        ret nz
        ld hl,(fields)
        inc hl
        ld (fields),hl
        ret

print5s:
        ld (ptmp),de
        call print5
        push de
        ld hl,(ptmp)
        ld b,4
        call supp
        pop de
        ret
supp:   ld a,(hl)
        cp $30
        ret nz
        ld (hl),$20
        inc hl
        djnz supp
        ret
print5: ld bc,$D8F0             ; -10000
        call dig
        ld bc,$FC18             ; -1000
        call dig
        ld bc,$FF9C             ; -100
        call dig
        ld bc,$FFF6             ; -10
        call dig
        ld a,l
        add a,$30
        ld (de),a
        inc de
        ret
dig:    ld a,$2F
dg1:    inc a
        add hl,bc
        jr c,dg1
        sbc hl,bc
        ld (de),a
        inc de
        ret

; ---------------- render one frame ------------------------------
render: ld hl,(m_cols)
        ld (colptr),hl
        ld a,(m_ncols)
        ld (colcnt),a
        ld hl,(m_hand)
        ld (rcall+1),hl
rcol:   call poll
rcall:  call 0                  ; self-modified: column handler for this mode
        ld hl,colcnt
        dec (hl)
        jp nz,rcol
        ret

; read the next column descriptor, cast its ray, return A = height index
nextray:
        ld hl,(colptr)
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,(hl)
        inc hl
        ld (fish),a
        ld c,(hl)
        inc hl
        ld b,(hl)
        inc hl
        ld (scrptr),bc
        ld c,(hl)
        inc hl
        ld b,(hl)
        inc hl
        ld (varptr),bc
        inc hl
        ld (colptr),hl
        ld hl,(pang)
        add hl,de
        ld a,h
        and 3
        ld h,a
        call castray
        jp height

setvar: ld hl,(varptr)
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (recbase),de
        ld a,(hl)
        inc hl
        ld (c_ceil+1),a
        ld a,(hl)
        inc hl
        ld (c_floor+1),a
        ret                     ; HL -> 4 flat wall colours, then texture page
gettexsel:
        ld a,(cell)
        dec a
        add a,a
        ld e,a
        ld a,(side)
        add a,e
        ret

; flat-shaded column
h_flat: call nextray
        call setvar
        call gettexsel
        ld e,a
        ld d,0
        add hl,de
        ld a,(hl)
        ld (c_wall+1),a
        ld a,(hidx)
        jp drawcol

; textured column, one screen byte wide
h_tex:  call nextray
        call setvar
        ld de,4
        add hl,de
        ld a,(hl)
        ld (texpage),a
        call texsrc
        call texcopy
        ld a,(hidx)
        jp drawcol

; two textured half-byte columns drawn as one pass
h_pair: call nextray
        ld (hl_i),a
        ld a,TEXL_HI
        ld (texpage),a
        call texsrc
        ld (tpl),hl
        call poll
        call nextray
        ld (hr_i),a
        ld a,TEXR_HI
        ld (texpage),a
        call texsrc
        ld (tpr),hl
        ld a,(hl_i)
        ld b,a
        ld a,(hr_i)
        sub b
        jr nc,pr_r
        neg                     ; left is taller
        cp 4
        ld a,b
        ld (hidx),a
        jr c,pr_go
        ld hl,(tpl)             ; depth edge: nearer wall takes both halves
        ld a,h
        add a,4
        ld h,a
        ld (tpr),hl
        jr pr_go
pr_r:   cp 4
        ld a,(hr_i)
        ld (hidx),a
        jr c,pr_go
        ld hl,(tpr)
        ld a,h
        sub 4
        ld h,a
        ld (tpl),hl
pr_go:  ld hl,(tpl)
        call texcopy
        ld hl,(tpr)
        ld de,TEXBUF
        call MERGE
        call setvar
        ld a,(hidx)
        jp drawcol

; ---------------- cast one ray: HL = angle 0..1023 --------------
castray:
        ld (rang),hl
        ld a,h
        add a,a
        add a,a
        ld e,a
        ld d,0
        ld hl,QTAB
        add hl,de
        ld a,(hl)
        ld (xop),a
        inc hl
        ld a,(hl)
        ld (yadd+1),a
        inc hl
        ld a,(hl)
        ld (xneg),a
        inc hl
        ld a,(hl)
        ld (yneg),a
        ld hl,(rang)            ; x: delta and first boundary distance
        ld a,h
        add a,DXLO_HI
        ld h,a
        ld e,(hl)
        ld a,e
        ld (sxlo+1),a
        ld a,h
        add a,4
        ld h,a
        ld d,(hl)
        ld a,d
        ld (sxhi+1),a
        ld a,(xneg)
        or a
        ld a,(px)
        jr nz,cx1
        cpl
cx1:    call mul816
        ld l,h
        ld h,a
        ld (sidex),hl
        ld hl,(rang)            ; y
        ld a,h
        add a,DYLO_HI
        ld h,a
        ld e,(hl)
        ld a,e
        ld (sylo+1),a
        ld a,h
        add a,4
        ld h,a
        ld d,(hl)
        ld a,d
        ld (syhi+1),a
        ld a,(yneg)
        or a
        ld a,(py)
        jr nz,cy1
        cpl
cy1:    call mul816
        ld e,h
        ld d,a                  ; DE = side distance y
        ld a,(py+1)
        add a,a
        add a,a
        add a,a
        add a,a
        ld c,a
        ld a,(px+1)
        or c
        ld c,a
        ld b,MAP_HI             ; BC -> map cell
        ld hl,(sidex)           ; HL = side distance x
dda:    or a
        sbc hl,de
        add hl,de
        jr nc,stepy
xop:    inc c                   ; self-modified: inc c / dec c
        ld a,(bc)
        or a
        jr nz,hitx
        ld a,l
sxlo:   add a,0
        ld l,a
        ld a,h
sxhi:   adc a,0
        ld h,a
        jp dda
stepy:  ld a,c
yadd:   add a,16                ; self-modified: +16 / -16
        ld c,a
        ld a,(bc)
        or a
        jr nz,hity
        ld a,e
sylo:   add a,0
        ld e,a
        ld a,d
syhi:   adc a,0
        ld d,a
        jp dda
hitx:   ld (cell),a
        xor a
        ld (side),a
        ld (dist),hl
        ret
hity:   ld (cell),a
        ld a,1
        ld (side),a
        ld (dist),de
        ret

; ---------------- distance -> height index ----------------------
height: ld hl,(dist)
        ld a,h
        cp 16
        jr c,ht1
        ld hl,$0FFF
ht1:    srl h
        rr l
        srl h
        rr l
        ld a,h
        add a,LOGD_HI
        ld h,a
        ld a,(hl)
        ld hl,fish
        sub (hl)                ; fisheye correction in the log domain
        jr nc,ht2
        xor a
ht2:    ld l,a
        ld h,HITAB_HI
        ld a,(hl)
        ld (hidx),a
        ret

; ---------------- texture column source -> HL ------------------
texsrc: ld hl,(rang)
        ld a,(side)
        or a
        jr nz,gty
        ld a,h
        add a,ASIN_HI
        ld h,a
        ld a,(hl)
        ld de,(dist)
        call mul816
        ld a,(yneg)
        or a
        ld a,(py)
        jr nz,gts
        add a,h
        jr gtd
gty:    ld a,h
        add a,ACOS_HI
        ld h,a
        ld a,(hl)
        ld de,(dist)
        call mul816
        ld a,(xneg)
        or a
        ld a,(px)
        jr nz,gts
        add a,h
        jr gtd
gts:    sub h
gtd:    and $F0
        ld l,a
        call gettexsel
        ld h,a
        ld a,(texpage)
        add a,h
        ld h,a
        ret
texcopy:
        ld de,TEXBUF
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ldi
        ret

; ---------------- draw one column: A = height index -------------
drawcol:
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,(recbase)
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (dc1+1),de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (dc2+1),de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (dc3+1),de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        push hl
        exx
        pop bc                  ; BC' -> row scaling table
        ld h,TEXBUF_HI          ; HL' -> texture column
        exx
        ld hl,(scrptr)
        ld de,32
c_ceil: ld c,0
dc1:    call 0
c_wall: ld c,0
dc2:    call 0
c_floor: ld c,0
dc3:    call 0
        ret

; ---------------- data -------------------------------------------
QTAB:   db $0C,$10,0,0
        db $0D,$10,1,0
        db $0D,$F0,1,1
        db $0C,$F0,0,1
EXPECT: dw 0,0,0,0              ; simulator results, patched by build.py
px:     dw 0
py:     dw 0
pang:   dw 0
vx:     dw 0
vy:     dw 0
rang:   dw 0
sidex:  dw 0
dist:   dw 0
fields: dw 0
pathptr: dw 0
colptr: dw 0
scrptr: dw 0
varptr: dw 0
recbase: dw 0
scrpos: dw 0
val:    dw 0
ptmp:   dw 0
m_ncols: db 0
m_hand: dw 0
m_cols: dw 0
tpl:    dw 0
tpr:    dw 0
hl_i:   db 0
hr_i:   db 0
steps:  db 0
results: dw 0,0,0,0
numbuf: ds 6
curtest: db 0
frcnt:  db 0
colcnt: db 0
lastfs: db 0
fish:   db 0
cell:   db 0
side:   db 0
xneg:   db 0
yneg:   db 0
hidx:   db 0
texsel: db 0
texpage: db 0
        ds 160
stacktop:
codeend:
